/** Clave normalizada de SKU alineada con normSkuKey (definida más abajo; versión local para el catálogo). */
function _skuKeyCatalog(s) {
  if (s == null) return "";
  let t = String(s).trim();
  if (t.endsWith(".0")) t = t.slice(0, -2);
  t = t.replace(/[^0-9A-Za-z]/g, "");
  if (/^\d+$/.test(t)) t = t.replace(/^0+/, "") || "0";
  return t.toUpperCase();
}
