// ============ UTILS ============
function pad9(id) {
  if (id == null) return null;
  let t = String(id).trim();
  if (t.endsWith(".0")) t = t.slice(0, -2);
  const d = t.replace(/[^0-9]/g, "");
  return d ? d.padStart(9, "0") : null;
}
function num(v) {
  if (v == null || v === "") return null;
  if (typeof v === "number") return Number.isFinite(v) ? v : null;
  let s = String(v).trim().replace(/\u00a0/g, " ").replace(/\s/g, "");
  if (!s) return null;
  // es-DO: 1.234,50  |  en-US: 1,234.50  |  simple: 1234.5 / 1234,5
  if (/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(s)) {
    // miles con punto, decimal con coma
    s = s.replace(/\./g, "").replace(",", ".");
  } else if (/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(s)) {
    // miles con coma, decimal con punto
    s = s.replace(/,/g, "");
  } else if (s.indexOf(",") >= 0 && s.indexOf(".") < 0) {
    s = s.replace(",", ".");
  } else {
    s = s.replace(/,/g, "");
  }
  const n = parseFloat(s);
  return Number.isFinite(n) ? n : null;
}
function toast(msg) {
  let stack = document.getElementById("toastStack");
  if (!stack) {
    stack = document.createElement("div");
    stack.id = "toastStack";
    stack.className = "toast-stack";
    stack.setAttribute("aria-live", "polite");
    document.body.appendChild(stack);
  }
  const el = document.createElement("div");
  el.className = "toast";
  el.textContent = msg;
  stack.appendChild(el);
  setTimeout(() => {
    el.style.opacity = "0";
    el.style.transition = "opacity .2s";
    setTimeout(() => el.remove(), 220);
  }, 2800);
}

/** Modal de confirmación propio (reemplaza window.confirm) */
function confirmDialog(message, opts) {
  opts = opts || {};
  return new Promise(resolve => {
    const overlay = document.getElementById("confirmOverlay");
    const titleEl = document.getElementById("confirmTitle");
    const msgEl = document.getElementById("confirmMsg");
    const btnOk = document.getElementById("btnConfirmOk");
    const btnCancel = document.getElementById("btnConfirmCancel");
    if (!overlay) { resolve(window.confirm(message)); return; }
    titleEl.textContent = opts.title || "Confirmar";
    msgEl.textContent = message;
    msgEl.style.whiteSpace = "pre-wrap";
    btnOk.textContent = opts.okText || "Confirmar";
    btnCancel.textContent = opts.cancelText || "Cancelar";
    if (opts.danger) {
      btnOk.className = "btn btn-danger btn-sm";
    } else {
      btnOk.className = "btn btn-primary btn-sm";
    }
    const prevFocus = document.activeElement;
    overlay.hidden = false;
    requestAnimationFrame(() => overlay.classList.add("visible"));
    btnOk.focus();
    function close(val) {
      overlay.classList.remove("visible");
      setTimeout(() => { overlay.hidden = true; }, 180);
      btnOk.onclick = null;
      btnCancel.onclick = null;
      overlay.onclick = null;
      document.removeEventListener("keydown", onKey);
      if (prevFocus && prevFocus.focus) try { prevFocus.focus(); } catch (e) {}
      resolve(val);
    }
    function onKey(e) {
      if (e.key === "Escape") close(false);
      if (e.key === "Enter") close(true);
    }
    btnOk.onclick = () => close(true);
    btnCancel.onclick = () => close(false);
    overlay.onclick = (e) => { if (e.target === overlay) close(false); };
    document.addEventListener("keydown", onKey);
  });
}

function setDropLoading(zoneId, on, textProcesando) {
  const z = document.getElementById(zoneId);
  if (!z) return;
  const t = z.querySelector(".t");
  if (on) {
    z.classList.add("loading");
    if (t && !t.dataset.orig) {
      t.dataset.orig = t.textContent;
      t.textContent = textProcesando || "Procesando…";
    }
  } else {
    z.classList.remove("loading");
    if (t && t.dataset.orig) {
      t.textContent = t.dataset.orig;
      delete t.dataset.orig;
    }
  }
}
function hoyStr() {
  return new Date().toLocaleDateString("es-DO", { weekday: "long", year: "numeric", month: "long", day: "numeric" });
}
function alias(row, keys) {
  const norm = s => String(s || "").trim().toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ");
  const ks = Object.keys(row);
  for (const a of keys) {
    const target = norm(a);
    const k = ks.find(x => norm(x) === target);
    if (k != null && row[k] != null && row[k] !== "") return row[k];
  }
  // partial: header contains key
  for (const a of keys) {
    const target = norm(a);
    const k = ks.find(x => norm(x).includes(target) || target.includes(norm(x)));
    if (k != null && row[k] != null && row[k] !== "") return row[k];
  }
  return null;
}
function normEstado(e) {
  const s = String(e || "").toUpperCase();
  if (s.includes("FACTURA")) return "Factura";
  if (s.includes("CONFIRMA")) return "Confirmación";
  return "Ninguno";
}

