// Operativo del día (panel, mapa, viajes, residuales) = SOLO este navegador / usuario logueado.
// NO se sube a GitHub. Catálogos compartidos (maestro, citas, topes, código, usuarios) sí.
function wsUserKey() {
  try {
    const u = (typeof usuarioActual === "function") ? usuarioActual() : null;
    if (u && u.id) return String(u.id);
  } catch (e) {}
  return "anon";
}
function wsKey(base) {
  return base + "__" + wsUserKey();
}
/** Migrar clave global antigua → por usuario (una sola vez). */
function wsMigrate(oldKey, newKey) {
  try {
    if (localStorage.getItem(newKey)) return;
    const v = localStorage.getItem(oldKey);
    if (v != null) localStorage.setItem(newKey, v);
  } catch (e) {}
}

function loadLS() {
  try {
    const c = localStorage.getItem("rutalog_citas");
    if (c) {
      const obj = JSON.parse(c);
      estado.citas = new Map(Object.entries(obj));
    }
    // Viajes: exclusivos del usuario en este navegador
    wsMigrate("rutalog_viajes", wsKey("rutalog_viajes"));
    const v = localStorage.getItem(wsKey("rutalog_viajes"));
    if (v) {
      const arr = JSON.parse(v);
      estado.viajesGuardados = arr;
      if (typeof renumerarViajes === "function") renumerarViajes();
      else estado.numViaje = arr.length + 1;
    } else {
      estado.viajesGuardados = [];
      estado.numViaje = 1;
    }
    const m = localStorage.getItem("rutalog_maestro");
    if (m) {
      const arr = JSON.parse(m);
      if (Array.isArray(arr) && arr.length) {
        estado.maestro.clear();
        arr.forEach(r => { if (r && r.id) estado.maestro.set(r.id, r); });
      }
    }
    const mf = localStorage.getItem("rutalog_maestro_fuente");
    if (mf) estado.maestroFuente = mf;
    const topesRaw = localStorage.getItem("rutalog_topes_sku");
    if (topesRaw) {
      const arr = JSON.parse(topesRaw);
      if (Array.isArray(arr)) {
        estado.topesSku.clear();
        arr.forEach(t => {
          if (!t || t.sku == null) return;
          const key = normSkuKey(t.sku);
          if (!key) return;
          const topeG = t.topeG != null ? Number(t.topeG) : (t.transporte === "CAMION P" ? 0 : Number(t.tope) || 0);
          const topeP = t.topeP != null ? Number(t.topeP) : (t.transporte === "CAMION P" ? Number(t.tope) || 0 : 0);
          estado.topesSku.set(key, {
            sku: String(t.sku).trim(),
            nombre: t.nombre || "",
            tope: Number(t.tope) || topeG || topeP || 0,
            topeG: topeG,
            topeP: topeP,
            transporte: t.transporte || "CAMION G",
          });
        });
      }
    } else {
      // Semilla de ejemplo (solo si nunca se guardó nada)
      const seed = [
        { sku: "1762", nombre: "", tope: 300, topeG: 300, topeP: 150, transporte: "CAMION G" },
        { sku: "3220", nombre: "", tope: 500, topeG: 500, topeP: 250, transporte: "CAMION G" },
        { sku: "1759", nombre: "", tope: 500, topeG: 500, topeP: 250, transporte: "CAMION G" },
        { sku: "3809", nombre: "", tope: 500, topeG: 500, topeP: 250, transporte: "CAMION G" },
        { sku: "184", nombre: "", tope: 500, topeG: 500, topeP: 250, transporte: "CAMION G" },
      ];
      seed.forEach(t => estado.topesSku.set(normSkuKey(t.sku), { ...t }));
    }
  } catch(e) {}
}
