// Auditoría de carga
const auditOverlay = document.getElementById("auditOverlay");
if (auditOverlay) {
  document.getElementById("btnAuditCancelar").onclick = cerrarAuditoria;
  document.getElementById("btnAuditVolver").onclick = cerrarAuditoria;
  document.getElementById("btnAuditConfirmar").onclick = confirmarAuditoriaYDespachar;
  document.getElementById("auditChkAll").onchange = function() {
    const on = this.checked;
    const vis = typeof indicesAuditVisibles === "function" ? indicesAuditVisibles() : estado.auditLineas.map((_, i) => i);
    vis.forEach(i => { estado.auditLineas[i].selected = on; });
    renderAuditoriaTabla();
  };
  // Filtros auditoría
  ["auditFilCliente","auditFilNombre","auditFilCiudad","auditFilSku","auditFilOV"].forEach(id => {
    const el = document.getElementById(id);
    if (!el || el._auditBound) return;
    el._auditBound = true;
    let t;
    el.addEventListener("input", () => {
      clearTimeout(t);
      t = setTimeout(() => { if (typeof renderAuditoriaTabla === "function") renderAuditoriaTabla(); }, 120);
    });
  });
  const btnLimpiar = document.getElementById("btnAuditLimpiarFiltro");
  if (btnLimpiar && !btnLimpiar._bound) {
    btnLimpiar._bound = true;
    btnLimpiar.onclick = () => {
      ["auditFilCliente","auditFilNombre","auditFilCiudad","auditFilSku","auditFilOV"].forEach(id => {
        const el = document.getElementById(id); if (el) el.value = "";
      });
      renderAuditoriaTabla();
    };
  }
  const btnSelVis = document.getElementById("btnAuditFiltrarSel");
  if (btnSelVis && !btnSelVis._bound) {
    btnSelVis._bound = true;
    btnSelVis.onclick = () => {
      indicesAuditVisibles().forEach(i => { estado.auditLineas[i].selected = true; });
      renderAuditoriaTabla();
    };
  }
  const btnDeselVis = document.getElementById("btnAuditFiltrarDesel");
  if (btnDeselVis && !btnDeselVis._bound) {
    btnDeselVis._bound = true;
    btnDeselVis.onclick = () => {
      indicesAuditVisibles().forEach(i => { estado.auditLineas[i].selected = false; });
      renderAuditoriaTabla();
    };
  }
  document.querySelectorAll('input[name="auditPlantilla"]').forEach(r => {
    r.onchange = function() {
      if (!this.checked) return;
      estado.plantillaCamion = this.value;
      if (typeof actualizarAuditStats === "function") actualizarAuditStats();
      else if (typeof renderAuditoriaTabla === "function") renderAuditoriaTabla();
      if (typeof actualizarAlertaTopesAuditoria === "function") actualizarAlertaTopesAuditoria();
    };
  });
  auditOverlay.addEventListener("click", e => {
    if (e.target === auditOverlay) cerrarAuditoria();
  });
  document.addEventListener("keydown", e => {
    if (e.key === "Escape" && auditOverlay && !auditOverlay.hidden) cerrarAuditoria();
  });
}

document.getElementById("btnLimpiarDia").onclick = async () => {
  const ok = await confirmDialog("¿Limpiar pedidos del día y viaje actual? (maestro y citas se conservan)", { title: "Limpiar día", danger: true });
  if (!ok) return;
  estado.clientesHoy = [];
  estado.viajeActual = [];
  estado.diarioRaw = [];
  estado.lineasRaw = [];
  estado.lineasPendientes = new Map();
  estado.controlOVs.clear();
  estado.origenActual = null;
  if (typeof clearDiarioEstado === "function") clearDiarioEstado();
  document.getElementById("sOV").textContent = "0";
  document.getElementById("sPeso").textContent = "0.00 kg";
  document.getElementById("sConf").textContent = "0";
  document.getElementById("sFact").textContent = "0";
  document.getElementById("sMapa").textContent = "0";
  document.getElementById("badgeMapaPanel").textContent = "0 puntos";
  refrescarRutaUI();
  renderDespachos();
  renderMapas();
  toast("Día limpiado");
};

document.getElementById("btnBorrarViajesTop").onclick = async () => {
  if (!estado.viajesGuardados.length && !estado.viajeActual.length) {
    toast("No hay viajes para borrar");
    return;
  }
  const ok = await confirmDialog("¿Borrar todos los viajes guardados y el viaje en curso?", { title: "Borrar viajes", danger: true });
  if (!ok) return;
  estado.viajesGuardados.forEach(v => {
    if (typeof restaurarLineasDeViaje === "function") restaurarLineasDeViaje(v);
  });
  estado.viajesGuardados = [];
  estado.viajeActual = [];
  estado.numViaje = 1;
  saveViajes();
  if (typeof saveDiarioEstado === "function") saveDiarioEstado();
  refrescarRutaUI();
  renderDespachos();
  if (typeof renderMapas === "function") renderMapas();
  toast("Viajes eliminados — líneas devueltas al mapa");
};

const btnCambiarCentro = document.getElementById("btnCambiarCentro");
if (btnCambiarCentro) btnCambiarCentro.onclick = () => abrirSelectorCentro({ forzar: true });

// Citas
document.getElementById("btnAddCita").onclick = () => {
  const id = pad9(document.getElementById("citaCliente").value);
  const fecha = document.getElementById("citaFecha").value;
  const ov = document.getElementById("citaOV").value.trim();
  if (!id || !fecha) { toast("ID cliente y fecha son obligatorios"); return; }
  estado.citas.set(id, { fecha, ov: ov || null });
  saveCitas();
  renderCitas();
  renderMapas();
  document.getElementById("citaCliente").value = "";
  document.getElementById("citaFecha").value = "";
  document.getElementById("citaOV").value = "";
  toast("Cita agregada");
};

