// Maestro Código UI
(function() {
  const q = document.getElementById("qCodigo");
  if (q) q.oninput = () => renderCodigoTable();
  const fil = document.getElementById("filCodigoUnd");
  if (fil) fil.onchange = () => renderCodigoTable();
  const btnAdd = document.getElementById("btnAddCodigo");
  if (btnAdd) btnAdd.onclick = agregarCodigoSku;
  ["codSku","codProducto","codUndCaja","codCajaPaleta"].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.addEventListener("keydown", e => { if (e.key === "Enter") { e.preventDefault(); agregarCodigoSku(); } });
  });
  const btnExp = document.getElementById("btnExportCodigo");
  if (btnExp) btnExp.onclick = exportarMaestroCodigo;
  const btnRst = document.getElementById("btnResetCodigo");
  if (btnRst) btnRst.onclick = resetMaestroCodigo;
  const btnImp = document.getElementById("btnImportCodigo");
  const fileImp = document.getElementById("fileImportCodigo");
  if (btnImp && fileImp) {
    btnImp.onclick = () => fileImp.click();
    fileImp.onchange = () => {
      if (fileImp.files && fileImp.files[0]) {
        importarMaestroCodigo(fileImp.files[0]);
        fileImp.value = "";
      }
    };
  }
})();

// Sidebar: móvil = drawer; escritorio = colapsar iconos (estilo Grok)
(function() {
  const sb = document.getElementById("sidebar");
  const bd = document.getElementById("sidebarBackdrop");
  const btn = document.getElementById("btnSidebarToggle");
  const btnCol = document.getElementById("btnCollapseSidebar");
  const LS_KEY = "rutalog_sidebar_collapsed";

  function closeMobile() {
    if (sb) sb.classList.remove("open");
    if (bd) { bd.classList.remove("show"); bd.hidden = true; }
  }
  function openMobile() {
    if (sb) sb.classList.add("open");
    if (bd) { bd.hidden = false; bd.classList.add("show"); }
  }
  const isDrawer = () => window.innerWidth <= 900;
  if (btn) btn.onclick = () => {
    if (isDrawer()) {
      if (sb && sb.classList.contains("open")) closeMobile(); else openMobile();
    } else if (sb) {
      sb.classList.toggle("collapsed");
      try { localStorage.setItem(LS_KEY, sb.classList.contains("collapsed") ? "1" : "0"); } catch (e) {}
      setTimeout(function() {
        try {
          if (estado.mapPanel) estado.mapPanel.invalidateSize();
          if (estado.mapRutas) estado.mapRutas.invalidateSize();
          if (estado.mapCruzados) estado.mapCruzados.invalidateSize();
        } catch (e) {}
      }, 220);
    }
  };
  if (btnCol) btnCol.onclick = () => {
    if (!sb) return;
    if (isDrawer()) {
      closeMobile();
      return;
    }
    sb.classList.toggle("collapsed");
    try { localStorage.setItem(LS_KEY, sb.classList.contains("collapsed") ? "1" : "0"); } catch (e) {}
    setTimeout(function() {
      try {
        if (estado.mapPanel) estado.mapPanel.invalidateSize();
        if (estado.mapRutas) estado.mapRutas.invalidateSize();
        if (estado.mapCruzados) estado.mapCruzados.invalidateSize();
      } catch (e) {}
    }, 220);
  };
  if (bd) {
    bd.onclick = closeMobile;
    bd.addEventListener("touchend", function(e) {
      e.preventDefault();
      closeMobile();
    }, { passive: false });
  }
  document.querySelectorAll(".nav button").forEach(b => {
    b.addEventListener("click", () => { if (isDrawer()) closeMobile(); });
  });
  // Restaurar estado colapsado solo en escritorio ancho
  try {
    if (!isDrawer() && localStorage.getItem(LS_KEY) === "1" && sb) {
      sb.classList.add("collapsed");
    }
  } catch (e) {}
  window.addEventListener("resize", function() {
    if (!isDrawer()) {
      closeMobile();
    } else if (sb) {
      sb.classList.remove("collapsed");
    }
  });
})();


