let resultadosReserva = [];
let detalleReserva = []; // filas por OV+SKU para hoja Detalle SKU

function normKeyReserva(s) {
  return String(s ?? "")
    .replace(/[\u00a0\u2000-\u200b\ufeff]/g, " ")
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}
function skuKeyReserva(s) {
  const t = String(s ?? "").trim().replace(/^0+/, "");
  return t || "0";
}
function undPorCajaReserva(sku) {
  if (typeof undPorCajaDeSku === "function") {
    const u = undPorCajaDeSku(sku);
    if (u && u > 0) return u;
  }
  const u = UND_CAJA[skuKeyReserva(sku)];
  return u && u > 0 ? u : null;
}
function isFisicaReserva(est) {
  const k = normKeyReserva(est);
  if (!k) return false;
  if (k.indexOf("fisica") !== -1 && k.indexOf("reserv") !== -1) return true;
  if (k === "reserved physical" || k === "physical reserved") return true;
  return false;
}
function clasificacionReserva(pct) {
  if (pct >= 99.9) return "Casi/total reservada";
  if (pct <= 0.05) return "Sin reserva física";
  return "Parcial";
}
function numReserva(v) {
  if (v == null || v === "") return 0;
  if (typeof v === "number" && Number.isFinite(v)) return v;
  if (typeof v === "string") {
    const n = parseFloat(v.replace(/\s/g, "").replace(",", "."));
    return Number.isFinite(n) ? n : 0;
  }
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
}
function buildColMapReserva(headerRow) {
  const map = {};
  headerRow.forEach((h, i) => {
    const k = normKeyReserva(h);
    if (k) map[k] = i;
  });
  return map;
}
function findColReserva(map, names, exclude) {
  exclude = exclude || [];
  for (const c of names) {
    const k = normKeyReserva(c);
    if (map[k] != null) return map[k];
  }
  const keys = Object.keys(map);
  for (const c of names) {
    const k = normKeyReserva(c);
    for (const x of keys) {
      if (x.indexOf(k) === -1) continue;
      let bad = false;
      for (const ex of exclude) {
        if (x.indexOf(normKeyReserva(ex)) !== -1) { bad = true; break; }
      }
      if (!bad) return map[x];
    }
  }
  return null;
}

function procesarSheetReserva(wb) {
  const sheet = wb.Sheets[wb.SheetNames[0]];
  const aoa = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: "", raw: true });
  if (!aoa.length) throw new Error("Hoja vacía");

  let headerIdx = 0, bestScore = -1;
  for (let i = 0; i < Math.min(20, aoa.length); i++) {
    const joined = (aoa[i] || []).map(normKeyReserva).join("|");
    let score = 0;
    if (joined.indexOf("orden de venta") !== -1 || joined.indexOf("sales order") !== -1) score += 3;
    if (joined.indexOf("cantidad reservada") !== -1) score += 3;
    if (joined.indexOf("liberacion") !== -1 || joined.indexOf("release status") !== -1) score += 2;
    if (joined.indexOf("codigo de articulo") !== -1) score += 1;
    if (score > bestScore) { bestScore = score; headerIdx = i; }
  }
  if (bestScore < 3) throw new Error("No se identificó el encabezado del export Dynamics.");

  const headerRow = (aoa[headerIdx] || []).map(h => String(h ?? "").trim());
  const map = buildColMapReserva(headerRow);
  const iOv = findColReserva(map, ["Orden de venta", "Sales order", "OV"]);
  const iSku = findColReserva(map, ["Código de artículo", "Codigo de articulo", "Item number", "SKU", "Articulo"]);
  const iRes = findColReserva(map, ["Cantidad reservada", "Reserved quantity"]);
  const iCant = findColReserva(map, ["Cantidad", "Quantity"], ["reserv"]);
  let iEst = findColReserva(map, ["Estado de la liberación", "Estado de la liberacion", "Release status", "Estado liberacion"], ["linea", "line", "order"]);
  if (iEst == null) {
    for (const [k, idx] of Object.entries(map)) {
      if (k.indexOf("liberacion") !== -1) { iEst = idx; break; }
    }
  }
  const iNeto = findColReserva(map, ["Monto neto", "Net amount", "Importe neto"]);
  const iUnidad = findColReserva(map, ["Unidad", "Unit", "UOM"]);

  if (iOv == null) throw new Error("No se encontró «Orden de venta». Headers: " + headerRow.slice(0, 8).join(", "));
  if (iRes == null) throw new Error("No se encontró «Cantidad reservada».");
  if (iCant == null) throw new Error("No se encontró «Cantidad» (pedido).");
  if (iEst == null) throw new Error("No se encontró «Estado de la liberación».");

  const byOvSku = new Map();
  let nRows = 0, nFisicaRows = 0;
  const estSamples = new Map();

  for (let r = headerIdx + 1; r < aoa.length; r++) {
    const row = aoa[r];
    if (!row || !row.length) continue;
    const ov = String(row[iOv] ?? "").trim();
    if (!ov) continue;
    nRows++;
    const sku = iSku != null ? String(row[iSku] ?? "").trim() : "";
    const est = String(row[iEst] ?? "").trim();
    estSamples.set(est, (estSamples.get(est) || 0) + 1);
    const res = Math.abs(numReserva(row[iRes]));
    const cant = Math.abs(numReserva(row[iCant]));
    const neto = iNeto != null ? Math.abs(numReserva(row[iNeto])) : 0;
    const unidad = iUnidad != null ? String(row[iUnidad] ?? "").trim() : "";
    const fisica = isFisicaReserva(est);
    if (fisica) nFisicaRows++;
    const key = ov + "\t" + sku;
    let rec = byOvSku.get(key);
    if (!rec) {
      rec = { ov, sku, unidad, cantPedida: 0, resFisica: 0, resTotal: 0, netoLinea: 0, nLin: 0, nFis: 0 };
      byOvSku.set(key, rec);
    }
    if (unidad && !rec.unidad) rec.unidad = unidad;
    rec.cantPedida = Math.max(rec.cantPedida, cant);
    rec.resTotal += res;
    rec.netoLinea = Math.max(rec.netoLinea, neto);
    rec.nLin += 1;
    if (fisica) {
      rec.resFisica += res;
      rec.nFis += 1;
    }
  }
  if (!nRows) throw new Error("No se leyeron filas de datos.");

  const byOv = new Map();
  detalleReserva = [];
  for (const rec of byOvSku.values()) {
    let o = byOv.get(rec.ov);
    if (!o) {
      o = { ov: rec.ov, resFisica: 0, pedidoUn: 0, netoTotal: 0, montoFisAprox: 0, nSku: 0, nFis: 0 };
      byOv.set(rec.ov, o);
    }
    const factor = undPorCajaReserva(rec.sku);
    const pedUn = factor ? rec.cantPedida * factor : Math.max(rec.cantPedida, rec.resTotal || 0);
    const ratioSku = pedUn > 0 ? Math.min(1, rec.resFisica / pedUn) : 0;
    const pctSku = Math.round(ratioSku * 10000) / 100;
    o.resFisica += rec.resFisica;
    o.pedidoUn += pedUn;
    o.netoTotal += rec.netoLinea;
    o.montoFisAprox += rec.netoLinea * ratioSku;
    o.nSku += 1;
    o.nFis += rec.nFis;

    detalleReserva.push({
      ov: rec.ov,
      sku: rec.sku,
      unidad: rec.unidad || "",
      cantPedida: rec.cantPedida,
      undCaja: factor != null ? factor : null,
      pedidoUn: Math.round(pedUn * 100) / 100,
      resFisica: Math.round(rec.resFisica * 100) / 100,
      resTotal: Math.round(rec.resTotal * 100) / 100,
      pctSku: pctSku,
      // pctOv se rellena después
      pctOv: 0,
    });
  }

  const out = [];
  for (const o of byOv.values()) {
    const pctRaw = o.pedidoUn > 0 ? (o.resFisica / o.pedidoUn) * 100 : 0;
    const pct = Math.min(pctRaw, 100);
    out.push({
      ov: o.ov,
      pct: Math.round(pct * 100) / 100,
      unFisica: Math.round(o.resFisica * 100) / 100,
      unPedido: Math.round(o.pedidoUn * 100) / 100,
      netoTotal: Math.round(o.netoTotal * 100) / 100,
      montoFisAprox: Math.round(o.montoFisAprox * 100) / 100,
      skus: o.nSku,
      lineasFis: o.nFis,
      clas: clasificacionReserva(pct),
    });
  }
  out.sort((a, b) => b.pct - a.pct || a.ov.localeCompare(b.ov));

  const pctByOv = new Map(out.map(r => [r.ov, r.pct]));
  for (const d of detalleReserva) d.pctOv = pctByOv.get(d.ov) || 0;
  detalleReserva.sort((a, b) => b.pctOv - a.pctOv || a.ov.localeCompare(b.ov) || String(a.sku).localeCompare(String(b.sku)));

  const estSummary = [...estSamples.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, 6)
    .map(([v, c]) => (v || "(vacío)") + ": " + c)
    .join(" · ");
  const st = document.getElementById("statusReserva");
  if (st) {
    st.textContent = "Procesadas " + nRows + " líneas → " + out.length + " OVs · Filas Física: " + nFisicaRows +
      (nFisicaRows === 0 ? " ⚠️" : "") + " | Estados: " + estSummary;
  }
  const err = document.getElementById("errReserva");
  if (err) {
    if (nFisicaRows === 0) {
      err.textContent = "Ninguna fila «Física reservada». Columna estado: «" + headerRow[iEst] + "». Valores: " + estSummary;
      err.style.display = "";
    } else {
      err.style.display = "none";
      err.textContent = "";
    }
  }
  return out;
}

function escReserva(s) {
  return String(s ?? "").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/"/g,"&quot;");
}
function fmtReserva(n) {
  return Number(n || 0).toLocaleString("es-DO", { maximumFractionDigits: 2 });
}
function fmtMoneyReserva(n) {
  return Number(n || 0).toLocaleString("es-DO", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function renderReserva() {
  const tb = document.getElementById("tbodyReserva");
  const empty = document.getElementById("emptyReserva");
  const stats = document.getElementById("statsReserva");
  const card = document.getElementById("cardReservaTable");
  if (!tb || !resultadosReserva.length) return;
  const clas = (document.getElementById("filtroClasReserva") || {}).value || "todas";
  const q = ((document.getElementById("filtroOVReserva") || {}).value || "").trim().toLowerCase();
  const filtrados = resultadosReserva.filter(r => {
    if (clas !== "todas" && r.clas !== clas) return false;
    if (q && !r.ov.toLowerCase().includes(q)) return false;
    return true;
  });
  const nFull = resultadosReserva.filter(r => r.clas === "Casi/total reservada").length;
  const nPart = resultadosReserva.filter(r => r.clas === "Parcial").length;
  const nZero = resultadosReserva.filter(r => r.clas === "Sin reserva física").length;
  document.getElementById("rsOVs").textContent = resultadosReserva.length;
  document.getElementById("rsFull").textContent = nFull;
  document.getElementById("rsPart").textContent = nPart;
  document.getElementById("rsZero").textContent = nZero;
  document.getElementById("rsVis").textContent = filtrados.length;
  stats.style.display = "";
  card.style.display = "";
  const badge = document.getElementById("badgeReserva");
  if (badge) badge.textContent = resultadosReserva.length + " OVs";
  if (!filtrados.length) {
    tb.innerHTML = "";
    empty.style.display = "";
    return;
  }
  empty.style.display = "none";
  tb.innerHTML = filtrados.map(r => {
    const color = r.clas === "Casi/total reservada" ? "var(--success)" : r.clas === "Parcial" ? "var(--warn)" : "var(--muted)";
    return "<tr>" +
      "<td class=\"mono\">" + escReserva(r.ov) + "</td>" +
      "<td class=\"mono\" style=\"font-weight:700;color:" + color + "\">" + r.pct.toFixed(2) + "%</td>" +
      "<td class=\"mono\">" + fmtReserva(r.unFisica) + "</td>" +
      "<td class=\"mono\">" + fmtReserva(r.unPedido) + "</td>" +
      "<td class=\"mono\">" + fmtMoneyReserva(r.netoTotal) + "</td>" +
      "<td class=\"mono\" style=\"font-weight:600;color:" + color + "\">" + fmtMoneyReserva(r.montoFisAprox) + "</td>" +
      "<td class=\"mono\">" + r.skus + "</td>" +
      "<td class=\"mono\">" + r.lineasFis + "</td>" +
      "<td><span class=\"badge\">" + escReserva(r.clas) + "</span></td>" +
      "</tr>";
  }).join("");
}

function descargarReserva() {
  if (!resultadosReserva.length) return;
  const clas = (document.getElementById("filtroClasReserva") || {}).value || "todas";
  const q = ((document.getElementById("filtroOVReserva") || {}).value || "").trim().toLowerCase();
  const filtrados = resultadosReserva.filter(r => {
    if (clas !== "todas" && r.clas !== clas) return false;
    if (q && !r.ov.toLowerCase().includes(q)) return false;
    return true;
  });
  const ovSet = new Set(filtrados.map(r => r.ov));
  const rowsOv = filtrados.map(r => ({
    "OV": r.ov,
    "% Reserva física": r.pct,
    "UN Física reservada": r.unFisica,
    "UN pedido (convertido)": r.unPedido,
    "Monto neto OV": r.netoTotal,
    "Monto reservado (aprox.)": r.montoFisAprox,
    "SKUs": r.skus,
    "Líneas Física": r.lineasFis,
    "Clasificación": r.clas,
  }));
  const rowsDet = detalleReserva
    .filter(d => ovSet.has(d.ov))
    .map(d => ({
      "OV": d.ov,
      "% OV": d.pctOv,
      "SKU": d.sku,
      "Unidad": d.unidad || "",
      "Cant. pedida": d.cantPedida,
      "Und/caja": d.undCaja != null ? d.undCaja : "—",
      "Pedido UN": d.pedidoUn,
      "Reserva física UN": d.resFisica,
      "Reserva total UN": d.resTotal,
      "% SKU": d.pctSku,
    }));
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(rowsOv), "Reserva por OV");
  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(rowsDet), "Detalle SKU");
  XLSX.writeFile(wb, "Porcentaje_Reserva_OV_" + new Date().toISOString().slice(0, 10) + ".xlsx");
  if (typeof toast === "function") toast("Descargado: " + rowsOv.length + " OVs · " + rowsDet.length + " líneas SKU");
}

async function cargarArchivoReserva(file) {
  const err = document.getElementById("errReserva");
  if (err) { err.style.display = "none"; err.textContent = ""; }
  if (!file) return;
  if (typeof XLSX === "undefined") {
    if (err) { err.textContent = "No cargó la librería XLSX. Hace falta conexión."; err.style.display = ""; }
    return;
  }
  const st = document.getElementById("statusReserva");
  if (st) st.textContent = "Leyendo " + file.name + "…";
  try {
    const buf = await file.arrayBuffer();
    const wb = XLSX.read(buf, { type: "array", cellDates: true });
    resultadosReserva = procesarSheetReserva(wb);
    if (!resultadosReserva.length) {
      if (err) { err.textContent = "No se generaron OVs. Revisa el export de Dynamics."; err.style.display = ""; }
      return;
    }
    const fc = document.getElementById("filtroClasReserva");
    const fo = document.getElementById("filtroOVReserva");
    if (fc) fc.value = "todas";
    if (fo) fo.value = "";
    renderReserva();
    if (typeof toast === "function") toast(resultadosReserva.length + " OVs · " + detalleReserva.length + " líneas SKU");
  } catch (e) {
    console.error(e);
    if (err) { err.textContent = String(e.message || e); err.style.display = ""; }
    if (st) st.textContent = "Error al procesar";
  }
}

(function initReservaPanel() {
  const drop = document.getElementById("dropReserva");
  const input = document.getElementById("fileReserva");
  if (!drop || !input) return;
  drop.addEventListener("click", () => input.click());
  drop.addEventListener("dragover", e => { e.preventDefault(); drop.classList.add("drag"); });
  drop.addEventListener("dragleave", () => drop.classList.remove("drag"));
  drop.addEventListener("drop", e => {
    e.preventDefault();
    drop.classList.remove("drag");
    const f = e.dataTransfer.files && e.dataTransfer.files[0];
    if (f) cargarArchivoReserva(f);
  });
  input.addEventListener("change", () => {
    if (input.files && input.files[0]) cargarArchivoReserva(input.files[0]);
  });
  const fc = document.getElementById("filtroClasReserva");
  const fo = document.getElementById("filtroOVReserva");
  const btn = document.getElementById("btnDescargarReserva");
  if (fc) fc.addEventListener("change", renderReserva);
  if (fo) fo.addEventListener("input", renderReserva);
  if (btn) btn.addEventListener("click", descargarReserva);
})();


/* ========== SYNC GITHUB (multi-PC) ========== */
const GH_SYNC = {
  owner: "luisglazala",
  repo: "rutalog-datos",
  path: "data.json",
  branch: "main",
  LS_TOKEN: "rutalog_gh_token",
  LS_META: "rutalog_gh_meta",
};

function ghGetToken() {
  try { return localStorage.getItem(GH_SYNC.LS_TOKEN) || ""; } catch (e) { return ""; }
}
function ghSetToken(tok) {
  try {
    if (tok) localStorage.setItem(GH_SYNC.LS_TOKEN, tok);
    else localStorage.removeItem(GH_SYNC.LS_TOKEN);
  } catch (e) {}
  ghUpdateSyncBadge();
}
function ghGetMeta() {
  try { return JSON.parse(localStorage.getItem(GH_SYNC.LS_META) || "{}"); } catch (e) { return {}; }
}
function ghSetMeta(m) {
  try { localStorage.setItem(GH_SYNC.LS_META, JSON.stringify(m || {})); } catch (e) {}
  const st = document.getElementById("syncStatus");
  if (st) {
    if (m && m.updatedAt) {
      st.textContent = "Última sync: " + m.updatedAt + (m.action ? " · " + m.action : "") +
        (m.updatedBy ? " · " + m.updatedBy : "");
    } else {
      st.textContent = "Última sync: —";
    }
  }
}
function ghUpdateSyncBadge() {
  const b = document.getElementById("badgeSync");
  if (!b) return;
  b.textContent = ghGetToken() ? "token OK" : "sin configurar";
}

/** Última lectura buena del catálogo (protección anti-borrado). */
function ghSetLastGood(info) {
  try {
    localStorage.setItem("rutalog_gh_last_good", JSON.stringify({
      sha: info && info.sha || null,
      size: info && info.size || 0,
      users: info && info.users || 0,
      at: new Date().toISOString(),
    }));
  } catch (e) {}
  try { localStorage.removeItem("rutalog_gh_read_failed"); } catch (e) {}
}
function ghGetLastGood() {
  try { return JSON.parse(localStorage.getItem("rutalog_gh_last_good") || "null"); } catch (e) { return null; }
}
function ghMarkReadFailed(msg) {
  try {
    localStorage.setItem("rutalog_gh_read_failed", JSON.stringify({
      msg: String(msg || "read failed"),
      at: new Date().toISOString(),
    }));
  } catch (e) {}
}
function ghLastReadFailed() {
  try {
    const v = localStorage.getItem("rutalog_gh_read_failed");
    return !!(v && v.length > 2);
  } catch (e) { return false; }
}
function ghClearReadFailed() {
  try { localStorage.removeItem("rutalog_gh_read_failed"); } catch (e) {}
}


function ghUtf8ToB64(str) {
  const bytes = new TextEncoder().encode(str);
  let bin = "";
  bytes.forEach(c => { bin += String.fromCharCode(c); });
  return btoa(bin);
}
function ghB64ToUtf8(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new TextDecoder().decode(bytes);
}

function ghMarkDirty(reason) {
  try {
    localStorage.setItem("rutalog_gh_dirty", "1");
    localStorage.setItem("rutalog_gh_dirty_at", new Date().toISOString());
    if (reason) localStorage.setItem("rutalog_gh_dirty_why", String(reason));
  } catch (e) {}
}
function ghClearDirty() {
  try {
    localStorage.removeItem("rutalog_gh_dirty");
    localStorage.removeItem("rutalog_gh_dirty_at");
    localStorage.removeItem("rutalog_gh_dirty_why");
  } catch (e) {}
}
function ghIsDirty() {
  try { return localStorage.getItem("rutalog_gh_dirty") === "1"; } catch (e) { return false; }
}

/** Tras cualquier cambio: marca dirty y sincroniza con GitHub en ~1.5 s (sube si hay cambios locales; baja si la nube está más nueva). */
let _ghPushTimer = null;
let _ghPushInFlight = false;
function ghSchedulePush(reason) {
  if (typeof _ghApplyingRemote !== "undefined" && _ghApplyingRemote) return;
  if (typeof _ghApplyingUsers !== "undefined" && _ghApplyingUsers) return;
  try { ghMarkDirty(reason || "edit"); } catch (e) {}
  let token = "";
  try { token = (typeof ghGetToken === "function") ? ghGetToken() : ""; } catch (e) {}
  if (!token) return;
  if (_ghPushTimer) clearTimeout(_ghPushTimer);
  _ghPushTimer = setTimeout(async function() {
    _ghPushTimer = null;
    if (_ghPushInFlight) {
      ghSchedulePush(reason || "retry");
      return;
    }
    if (typeof ghActualizar !== "function") return;
    _ghPushInFlight = true;
    try {
      // Sube cambios locales y/o baja si remoto es más nuevo
      await ghActualizar({ silent: true });
    } catch (e) {
      console.warn("ghSchedulePush", e);
    } finally {
      _ghPushInFlight = false;
    }
  }, 1500);
}

/** Sincronización periódica: baja cambios de otras PCs aunque esta no edite. */
let _ghPullTimer = null;
function ghStartPullLoop(on) {
  if (_ghPullTimer) { clearInterval(_ghPullTimer); _ghPullTimer = null; }
  if (!on) return;
  _ghPullTimer = setInterval(function() {
    if (document.hidden) return;
    if (typeof ghGetToken !== "function" || !ghGetToken()) return;
    if (_ghPushInFlight) return;
    if (typeof ghActualizar === "function") {
      ghActualizar({ silent: true }).catch(function() {});
    }
  }, 60 * 1000); // cada 60 s
}

function ghOnVisibilitySync() {
  if (document.hidden) return;
  if (typeof ghGetToken !== "function" || !ghGetToken()) return;
  if (_ghPushInFlight) return;
  if (typeof ghActualizar === "function") {
    setTimeout(function() {
      try { ghActualizar({ silent: true }); } catch (e) {}
    }, 400);
  }
}

function ghBuildPayload() {
  // Solo catálogos compartidos. NUNCA: diario, viajes, residuales, reserva OV, cruzados.
  const maestroArr = [];
  if (estado.maestro) estado.maestro.forEach(r => maestroArr.push(r));
  const citasObj = {};
  if (estado.citas) estado.citas.forEach((v, k) => { citasObj[k] = v; });
  const topesArr = [];
  if (estado.topesSku) estado.topesSku.forEach(t => topesArr.push({
    sku: t.sku,
    nombre: t.nombre || "",
    tope: Number(t.tope) || Number(t.topeG) || Number(t.topeP) || 0,
    topeG: t.topeG != null ? Number(t.topeG) : (Number(t.tope) || 0),
    topeP: t.topeP != null ? Number(t.topeP) : 0,
    transporte: t.transporte || "CAMION G",
  }));
  const codigoArr = [];
  if (estado.maestroCodigo) estado.maestroCodigo.forEach(r => codigoArr.push(r));
  let usuarios = [];
  try {
    if (typeof loadUsers === "function") usuarios = loadUsers();
  } catch (e) {}
  let updatedBy = null;
  try {
    if (typeof _sessionUser !== "undefined" && _sessionUser) {
      updatedBy = _sessionUser.username || _sessionUser.nombre || null;
    }
  } catch (e) {}
  return {
    version: 1,
    updatedAt: new Date().toISOString(),
    updatedBy: updatedBy,
    maestroClientes: maestroArr,
    maestroFuente: estado.maestroFuente || "sync",
    citas: citasObj,
    topesSku: topesArr,
    codigoSku: codigoArr,
    usuarios: usuarios,
  };
}

function ghApplyPayload(data, opts) {
  opts = opts || {};
  if (!data || typeof data !== "object") throw new Error("JSON inválido");
  _ghApplyingRemote = true;
  try {

  if (Array.isArray(data.maestroClientes)) {
    estado.maestro.clear();
    data.maestroClientes.forEach(r => {
      if (r && r.id) estado.maestro.set(String(r.id), r);
    });
    estado.maestroFuente = data.maestroFuente || "github";
    estado.maestroByBare = new Map();
    estado.maestro.forEach((r, id) => {
      const bare = String(id).replace(/^0+/, "") || "0";
      if (!estado.maestroByBare.has(bare)) estado.maestroByBare.set(bare, r);
    });
    try { saveMaestroLS(); } catch (e) {}
    try {
      const badge = document.getElementById("badgeMaestro");
      if (badge) badge.textContent = estado.maestro.size;
      const foot = document.getElementById("footStats");
      if (foot) foot.textContent = estado.maestro.size.toLocaleString() + " clientes · github";
      if (typeof actualizarFuenteMaestroUI === "function") actualizarFuenteMaestroUI();
      if (typeof fillProvFilter === "function") fillProvFilter();
      if (typeof renderMaestroTable === "function") renderMaestroTable();
    } catch (e) {}
  }

  if (data.citas && typeof data.citas === "object") {
    estado.citas = new Map(Object.entries(data.citas));
    try { saveCitas(); } catch (e) {}
    try { if (typeof renderCitas === "function") renderCitas(); } catch (e) {}
  }

  if (Array.isArray(data.topesSku)) {
    if (data.topesSku.length > 0) {
      estado.topesSku.clear();
      data.topesSku.forEach(t => {
        if (!t || t.sku == null) return;
        const key = typeof normSkuKey === "function" ? normSkuKey(t.sku) : String(t.sku);
        // Compat: datos viejos solo tenían "tope"; los nuevos traen topeG / topeP
        let topeG = t.topeG != null ? Number(t.topeG) : null;
        let topeP = t.topeP != null ? Number(t.topeP) : null;
        const topeLegacy = Number(t.tope) || 0;
        if (topeG == null || !Number.isFinite(topeG)) {
          topeG = (t.transporte === "CAMION P") ? 0 : topeLegacy;
        }
        if (topeP == null || !Number.isFinite(topeP)) {
          topeP = (t.transporte === "CAMION P") ? topeLegacy : 0;
        }
        estado.topesSku.set(key, {
          sku: String(t.sku).trim(),
          nombre: t.nombre || "",
          tope: topeG || topeP || topeLegacy,
          topeG: topeG,
          topeP: topeP,
          transporte: t.transporte || "CAMION G",
        });
      });
      try {
        const arr = [];
        estado.topesSku.forEach(x => arr.push({
          sku: x.sku,
          nombre: x.nombre || "",
          tope: Number(x.tope) || Number(x.topeG) || Number(x.topeP) || 0,
          topeG: x.topeG != null ? Number(x.topeG) : 0,
          topeP: x.topeP != null ? Number(x.topeP) : 0,
          transporte: x.transporte || "CAMION G",
        }));
        localStorage.setItem("rutalog_topes_sku", JSON.stringify(arr));
      } catch (e) {}
      try { if (typeof renderTopesTable === "function") renderTopesTable(); } catch (e) {}
    } else if (estado.topesSku && estado.topesSku.size > 0) {
      try { if (typeof ghMarkDirty === "function") ghMarkDirty("topes-local"); } catch (e) {}
    }
  }

  if (Array.isArray(data.codigoSku)) {
    if (data.codigoSku.length > 0) {
      estado.maestroCodigo.clear();
      data.codigoSku.forEach(r => {
        if (!r || r.sku == null) return;
        const key = typeof normSkuKey === "function" ? normSkuKey(r.sku) : String(r.sku);
        estado.maestroCodigo.set(key, {
          sku: r.sku,
          producto: r.producto || "",
          undCaja: r.undCaja != null ? r.undCaja : null,
          cajaPaleta: r.cajaPaleta != null ? r.cajaPaleta : null,
          undPaleta: r.undPaleta != null ? r.undPaleta : null,
        });
      });
      estado.maestroCodigoFuente = "github (" + estado.maestroCodigo.size + " SKU)";
      try { localStorage.removeItem("rutalog_maestro_codigo"); } catch (e) {}
      try { if (typeof renderCodigoTable === "function") renderCodigoTable(); } catch (e) {}
    } else if (estado.maestroCodigo && estado.maestroCodigo.size > 0) {
      try { if (typeof ghMarkDirty === "function") ghMarkDirty("codigo-local"); } catch (e) {}
    }
  }

  // Usuarios (hashes; repo privado). No borrar locales si el remoto viene vacío.
  if (Array.isArray(data.usuarios) && typeof saveUsers === "function") {
    try {
      const localUsers = (typeof loadUsers === "function") ? loadUsers() : [];
      if (data.usuarios.length > 0) {
        _ghApplyingUsers = true;
        try {
          saveUsers(data.usuarios);
        } finally {
          _ghApplyingUsers = false;
        }
        if (typeof aplicarGateLoginDesdeSync === "function") aplicarGateLoginDesdeSync();
        else {
          if (typeof renderUsuariosTable === "function") renderUsuariosTable();
          if (typeof aplicarPermisosUI === "function") aplicarPermisosUI();
        }
      } else if (localUsers.length > 0) {
        // remoto sin usuarios pero local sí → marcar dirty para subirlos en el push
        try { if (typeof ghMarkDirty === "function") ghMarkDirty("usuarios-local"); } catch (e) {}
      }
    } catch (e) { console.warn("apply usuarios", e); _ghApplyingUsers = false; }
  }

  ghSetMeta({
    updatedAt: data.updatedAt || new Date().toISOString(),
    updatedBy: data.updatedBy || null,
    action: opts.action || "bajado",
  });
  } finally {
    _ghApplyingRemote = false;
  }
}

let _ghFetchInflight = null;
async function ghFetchFile(opts) {
  opts = opts || {};
  const force = !!opts.force;
  if (!force && _ghFetchInflight) return _ghFetchInflight;
  const run = _ghFetchFileInner(opts);
  if (!force) {
    _ghFetchInflight = run.finally(function() { _ghFetchInflight = null; });
    return _ghFetchInflight;
  }
  return run;
}
async function _ghFetchFileInner(opts) {
  opts = opts || {};
  const force = !!opts.force;
  const token = ghGetToken();
  if (!token) throw new Error("Configura el token de GitHub primero");
  const base = "https://api.github.com/repos/" + GH_SYNC.owner + "/" + GH_SYNC.repo;
  const pathEnc = GH_SYNC.path.split("/").map(encodeURIComponent).join("/");
  const metaUrl = base + "/contents/" + pathEnc + "?ref=" + encodeURIComponent(GH_SYNC.branch);
  const authHeaders = {
    "Authorization": "Bearer " + token,
    "X-GitHub-Api-Version": "2022-11-28",
  };

  // 1) SIEMPRE metadatos primero (petición pequeña → sha)
  let meta;
  try {
    const rMeta = await fetch(metaUrl, {
      headers: { ...authHeaders, "Accept": "application/vnd.github+json" },
    });
    if (rMeta.status === 401 || rMeta.status === 403) {
      try { if (typeof ghMarkReadFailed === "function") ghMarkReadFailed("HTTP " + rMeta.status); } catch (e2) {}
      throw new Error("Token inválido o sin permiso al repo (HTTP " + rMeta.status + "). Regenera el PAT.");
    }
    if (rMeta.status === 404) {
      try { if (typeof ghMarkReadFailed === "function") ghMarkReadFailed("404"); } catch (e2) {}
      throw new Error("No existe data.json en el repo");
    }
    if (!rMeta.ok) {
      const tx = await rMeta.text().catch(() => "");
      try { if (typeof ghMarkReadFailed === "function") ghMarkReadFailed("HTTP " + rMeta.status); } catch (e2) {}
      throw new Error("GitHub HTTP " + rMeta.status + " " + tx.slice(0, 120));
    }
    meta = await rMeta.json();
  } catch (e) {
    if (String(e.message || "").includes("Token") || String(e.message || "").includes("No existe") || String(e.message || "").includes("GitHub HTTP")) throw e;
    try { if (typeof ghMarkReadFailed === "function") ghMarkReadFailed("network"); } catch (e2) {}
    throw new Error("Sin conexión a GitHub (Failed to fetch). Revisa internet.");
  }

  // 2) Si el sha coincide con la última lectura buena, no re-descargar
  let lastSha = null;
  try { lastSha = localStorage.getItem("rutalog_gh_sha") || null; } catch (e) {}
  const lg = typeof ghGetLastGood === "function" ? ghGetLastGood() : null;
  if (!force && meta.sha && lastSha && meta.sha === lastSha && lg && lg.sha === meta.sha) {
    return { sha: meta.sha, data: null, size: lg.size || 0, unchanged: true };
  }

  // 3a) content en base64 (archivos ≤ ~1 MB)
  if (meta.content) {
    const text = ghB64ToUtf8(String(meta.content).replace(/\n/g, ""));
    if (!text.trim()) {
      try { if (typeof ghMarkReadFailed === "function") ghMarkReadFailed("content vacío"); } catch (e2) {}
      throw new Error("data.json vacío");
    }
    let data;
    try { data = JSON.parse(text); } catch (e) {
      try { if (typeof ghMarkReadFailed === "function") ghMarkReadFailed("JSON"); } catch (e2) {}
      throw new Error("data.json incompleto: " + (e.message || "JSON"));
    }
    if (typeof ghSetLastGood === "function") {
      ghSetLastGood({
        sha: meta.sha,
        size: text.length,
        users: Array.isArray(data.usuarios) ? data.usuarios.length : 0,
      });
    }
    return { sha: meta.sha, data: data, size: text.length, unchanged: false };
  }

  // 3b) Archivo grande: Git Blob API
  if (!meta.sha) {
    try { if (typeof ghMarkReadFailed === "function") ghMarkReadFailed("sin sha"); } catch (e2) {}
    throw new Error("GitHub no devolvió SHA de data.json");
  }
  let blob;
  try {
    const rBlob = await fetch(base + "/git/blobs/" + meta.sha, {
      headers: { ...authHeaders, "Accept": "application/vnd.github+json" },
    });
    if (!rBlob.ok) {
      const tx = await rBlob.text().catch(() => "");
      try { if (typeof ghMarkReadFailed === "function") ghMarkReadFailed("blob " + rBlob.status); } catch (e2) {}
      throw new Error("Blob HTTP " + rBlob.status + " " + tx.slice(0, 100));
    }
    blob = await rBlob.json();
  } catch (e) {
    if (String(e.message || "").startsWith("Blob HTTP")) throw e;
    try { if (typeof ghMarkReadFailed === "function") ghMarkReadFailed("blob network"); } catch (e2) {}
    throw new Error("No se pudo leer data.json grande (blob). " + (e.message || e));
  }

  let text = "";
  if (blob.encoding === "base64" && blob.content) {
    text = ghB64ToUtf8(String(blob.content).replace(/\n/g, ""));
  } else if (blob.content) {
    text = String(blob.content);
  }
  if (!text || !text.trim()) {
    try { if (typeof ghMarkReadFailed === "function") ghMarkReadFailed("blob vacío"); } catch (e2) {}
    throw new Error("Blob de data.json vacío");
  }
  let data;
  try {
    data = JSON.parse(text);
  } catch (e) {
    try { if (typeof ghMarkReadFailed === "function") ghMarkReadFailed("JSON blob"); } catch (e2) {}
    throw new Error("data.json incompleto: " + (e.message || "JSON") + " (" + text.length + " chars)");
  }
  if (typeof ghSetLastGood === "function") {
    ghSetLastGood({
      sha: meta.sha,
      size: text.length,
      users: Array.isArray(data.usuarios) ? data.usuarios.length : 0,
    });
  }
  return { sha: meta.sha, data: data, size: text.length, unchanged: false };
}

async function ghApi(path, opts) {
  opts = opts || {};
  const token = ghGetToken();
  if (!token) throw new Error("Configura el token de GitHub primero");
  const url = path.startsWith("http") ? path : ("https://api.github.com" + path);
  let res;
  try {
    res = await fetch(url, {
      method: opts.method || "GET",
      headers: {
        "Accept": "application/vnd.github+json",
        "Authorization": "Bearer " + token,
        "X-GitHub-Api-Version": "2022-11-28",
        ...(opts.body ? { "Content-Type": "application/json" } : {}),
      },
      body: opts.body ? JSON.stringify(opts.body) : undefined,
    });
  } catch (e) {
    throw new Error("Sin conexión a GitHub (Failed to fetch). Revisa internet.");
  }
  const text = await res.text().catch(() => "");
  let json = null;
  if (text) {
    try { json = JSON.parse(text); } catch (e) { json = null; }
  }
  if (!res.ok) {
    const msg = (json && json.message) ? json.message : text.slice(0, 160);
    throw new Error("GitHub HTTP " + res.status + " " + msg);
  }
  return json;
}

/** Subida fiable vía Git Data API (blob → tree → commit → ref). No depende del SHA del Contents API. */
async function ghPushWithSha(sha, silent) {
  const token = ghGetToken();
  if (!token) throw new Error("Configura el token de GitHub primero");

  if (typeof ghLastReadFailed === "function" && ghLastReadFailed()) {
    const msg = "Escritura bloqueada: la última lectura del catálogo falló o llegó vacía. No se sube para no borrar datos en la nube.";
    if (!silent && typeof toast === "function") toast(msg);
    throw new Error(msg);
  }

  const payload = ghBuildPayload();
  const jsonText = JSON.stringify(payload);

  try {
    const lg = typeof ghGetLastGood === "function" ? ghGetLastGood() : null;
    const usersNow = Array.isArray(payload.usuarios) ? payload.usuarios.length : 0;
    if (lg && lg.users > 0 && usersNow === 0) {
      const msg = "Escritura bloqueada: el catálogo local no tiene usuarios y la última lectura buena tenía " + lg.users + ". No se sube.";
      if (!silent && typeof toast === "function") toast(msg);
      throw new Error(msg);
    }
    if (lg && lg.size > 0 && jsonText.length < lg.size * 0.5) {
      const msg = "Escritura bloqueada: el contenido nuevo (" + jsonText.length + " B) es <50% de la última lectura buena (" + lg.size + " B).";
      if (!silent && typeof toast === "function") toast(msg);
      throw new Error(msg);
    }
  } catch (e) {
    if (String(e.message || "").indexOf("Escritura bloqueada") === 0) throw e;
  }
  const owner = GH_SYNC.owner;
  const repo = GH_SYNC.repo;
  const branch = GH_SYNC.branch || "main";
  const filePath = GH_SYNC.path || "data.json";

  // 1) Ref de la rama → commit actual
  let ref;
  try {
    ref = await ghApi("/repos/" + owner + "/" + repo + "/git/ref/heads/" + encodeURIComponent(branch));
  } catch (e) {
    // rama no existe o sin permiso
    throw new Error("No se pudo leer la rama " + branch + ": " + (e.message || e));
  }
  const parentCommitSha = ref && ref.object && ref.object.sha;
  if (!parentCommitSha) throw new Error("Rama sin commit HEAD");

  // 2) Commit actual → tree base
  const parentCommit = await ghApi("/repos/" + owner + "/" + repo + "/git/commits/" + parentCommitSha);
  const baseTreeSha = parentCommit && parentCommit.tree && parentCommit.tree.sha;
  if (!baseTreeSha) throw new Error("Commit sin tree");

  // 3) Crear blob con el contenido (utf-8 directo; GitHub acepta encoding utf-8)
  const blob = await ghApi("/repos/" + owner + "/" + repo + "/git/blobs", {
    method: "POST",
    body: {
      content: jsonText,
      encoding: "utf-8",
    },
  });
  if (!blob || !blob.sha) throw new Error("No se creó el blob de data.json");

  // 4) Nuevo tree con data.json apuntando al blob
  const tree = await ghApi("/repos/" + owner + "/" + repo + "/git/trees", {
    method: "POST",
    body: {
      base_tree: baseTreeSha,
      tree: [{
        path: filePath,
        mode: "100644",
        type: "blob",
        sha: blob.sha,
      }],
    },
  });
  if (!tree || !tree.sha) throw new Error("No se creó el tree");

  // 5) Commit
  const msg = "RUTALOG sync " + (payload.updatedAt || "") + (payload.updatedBy ? " · " + payload.updatedBy : "");
  const commit = await ghApi("/repos/" + owner + "/" + repo + "/git/commits", {
    method: "POST",
    body: {
      message: msg,
      tree: tree.sha,
      parents: [parentCommitSha],
    },
  });
  if (!commit || !commit.sha) throw new Error("No se creó el commit");

  // 6) Mover la ref de la rama
  await ghApi("/repos/" + owner + "/" + repo + "/git/refs/heads/" + encodeURIComponent(branch), {
    method: "PATCH",
    body: { sha: commit.sha, force: false },
  });

  try { localStorage.setItem("rutalog_gh_sha", blob.sha); } catch (e) {}
  try { localStorage.setItem("rutalog_gh_remote_at", payload.updatedAt); } catch (e) {}
  ghClearDirty();
  ghSetMeta({
    updatedAt: payload.updatedAt,
    updatedBy: payload.updatedBy,
    action: "subido",
  });
  if (!silent && typeof toast === "function") {
    toast("Subido · " + payload.maestroClientes.length + " clientes · " +
      Object.keys(payload.citas).length + " citas · " + payload.topesSku.length + " topes · " +
      payload.codigoSku.length + " códigos · " + (payload.usuarios || []).length + " usuarios");
  }
  return payload;
}

/** Actualizar: baja remoto; si local dirty o remoto vacío de datos locales, sube. */
async function ghActualizar(opts) {
  opts = opts || {};
  const silent = !!opts.silent;
  try {
    if (!ghGetToken()) {
      if (!silent) toast("Configura el token de GitHub primero");
      return;
    }
    if (!silent) toast("Actualizando con GitHub…");

    let remote = null;
    try {
      remote = await ghFetchFile();
    } catch (e) {
      try { if (typeof ghMarkReadFailed === "function") ghMarkReadFailed(e.message || e); } catch (e2) {}
      if (String(e.message || "").includes("No existe")) {
        await ghPushWithSha(null, silent);
        return;
      }
      throw e;
    }
    if (remote && remote.unchanged) {
      if (!silent && typeof toast === "function") toast("Catálogo al día (sin cambios)");
      return;
    }
    if (remote && remote.data == null && !remote.unchanged) {
      try { if (typeof ghMarkReadFailed === "function") ghMarkReadFailed("data null"); } catch (e2) {}
      throw new Error("No se pudo leer el catálogo: data.json vacío en la respuesta.");
    }

    const remoteAt = (remote.data && remote.data.updatedAt) || "";
    let localRemoteAt = "";
    try { localRemoteAt = localStorage.getItem("rutalog_gh_remote_at") || ""; } catch (e) {}

    const remoteIsNewer = remoteAt && remoteAt !== localRemoteAt && remoteAt > localRemoteAt;
    const dirty = ghIsDirty();

    // 1) Conflicto: local dirty + remoto más nuevo → preguntar
    if (remoteIsNewer && dirty) {
      let choice = "bajar";
      if (!silent && typeof confirmDialog === "function") {
        const okSubir = await confirmDialog(
          "Hay cambios en esta PC y también en GitHub (más recientes en la nube).\n\n" +
          "• Confirmar = SUBIR lo de esta PC (pisa la nube)\n" +
          "• Cancelar = BAJAR lo de la nube (pisa lo local)",
          { title: "Conflicto de sincronización", okText: "Subir esta PC", danger: true }
        );
        choice = okSubir ? "subir" : "bajar";
      } else if (silent) {
        // Auto-sync: la nube gana en catálogos compartidos (topes, usuarios, maestro…)
        // para que todas las PCs vean Tope P, roles, etc. sin intervención manual.
        ghApplyPayload(remote.data, { action: "bajado-auto" });
        try {
          localStorage.setItem("rutalog_gh_sha", remote.sha);
          localStorage.setItem("rutalog_gh_remote_at", remoteAt || "");
        } catch (e) {}
        ghClearDirty();
        ghSetMeta({
          updatedAt: remoteAt || new Date().toISOString(),
          updatedBy: (remote.data && remote.data.updatedBy) || null,
          action: "bajado (auto, remoto más nuevo)",
        });
        return;
      }
      if (choice === "subir") {
        await ghPushWithSha(remote.sha, silent);
        return;
      }
      // bajar
      ghApplyPayload(remote.data, { action: "bajado" });
      try {
        localStorage.setItem("rutalog_gh_sha", remote.sha);
        localStorage.setItem("rutalog_gh_remote_at", remoteAt || "");
      } catch (e) {}
      ghClearDirty();
      if (!silent) {
        const d = remote.data || {};
        toast("Bajado desde GitHub (se descartaron cambios locales no subidos)");
      }
      return;
    }

    // 2) Remoto más nuevo (local limpio) o primera vez → bajar
    if (remoteIsNewer || !localRemoteAt) {
      ghApplyPayload(remote.data, { action: "bajado" });
      try {
        localStorage.setItem("rutalog_gh_sha", remote.sha);
        localStorage.setItem("rutalog_gh_remote_at", remoteAt || "");
      } catch (e) {}
      if (remoteIsNewer) ghClearDirty();
      if (!silent) {
        const d = remote.data || {};
        toast("Actualizado desde GitHub · " +
          (d.maestroClientes || []).length + " clientes · " +
          Object.keys(d.citas || {}).length + " citas · " +
          (d.topesSku || []).length + " topes · " +
          (d.codigoSku || []).length + " códigos · " +
          (d.usuarios || []).length + " usuarios");
      }
      if (!remoteIsNewer && dirty) {
        await ghPushWithSha(remote.sha, silent);
      }
      return;
    }

    // 3) Remoto igual o más viejo + dirty local → subir
    if (dirty) {
      await ghPushWithSha(remote.sha, silent);
      return;
    }

    // 4) Nada que hacer
    try { localStorage.setItem("rutalog_gh_sha", remote.sha); } catch (e) {}
    ghSetMeta({
      updatedAt: remoteAt || new Date().toISOString(),
      updatedBy: (remote.data && remote.data.updatedBy) || null,
      action: "al día",
    });
    if (!silent) toast("Ya está al día con GitHub");
  } catch (e) {
    console.error(e);
    if (!silent && typeof toast === "function") toast("Error al actualizar: " + (e.message || e));
  }
}

// Hooks: marcar dirty al guardar paneles sincronizados
(function wrapDirtyHooks() {
  function wrap(name, fnName) {
    try {
      const orig = window[fnName] || (typeof eval === "function" ? null : null);
    } catch (e) {}
  }
  const pairs = [
    ["saveMaestroLS", "maestro"],
    ["saveCitas", "citas"],
    ["saveTopesSku", "topes"],
    ["saveMaestroCodigoLS", "codigo"],
    ["saveUsers", "usuarios"],
  ];
  // Se enganchan después de definir las funciones — ver ghInstallDirtyHooks
})();

function ghInstallDirtyHooks() {
  function wrap(fnName, tag) {
    if (typeof window[fnName] === "function" && !window[fnName]._ghWrapped) {
      const orig = window[fnName];
      const wrapped = function() {
        const r = orig.apply(this, arguments);
        ghMarkDirty(tag);
        return r;
      };
      wrapped._ghWrapped = true;
      // funciones están en scope global del script, no window — usar reasignación local via eval no
      // En este HTML las funciones son globales de script; las reasignamos en el mismo scope:
      try {
        // eslint-disable-next-line no-eval
      } catch (e) {}
    }
  }
  // Re-wrap in global scope by direct assignment if they exist as globals
  try {
    if (typeof saveMaestroLS === "function" && !saveMaestroLS._ghWrapped) {
      const o = saveMaestroLS;
      saveMaestroLS = function() { const r = o.apply(this, arguments); ghMarkDirty("maestro"); return r; };
      saveMaestroLS._ghWrapped = true;
    }
  } catch (e) {}
  try {
    if (typeof saveCitas === "function" && !saveCitas._ghWrapped) {
      const o = saveCitas;
      saveCitas = function() { const r = o.apply(this, arguments); ghMarkDirty("citas"); return r; };
      saveCitas._ghWrapped = true;
    }
  } catch (e) {}
  try {
    if (typeof saveTopesSku === "function" && !saveTopesSku._ghWrapped) {
      const o = saveTopesSku;
      saveTopesSku = function() { const r = o.apply(this, arguments); ghMarkDirty("topes"); return r; };
      saveTopesSku._ghWrapped = true;
    }
  } catch (e) {}
  try {
    if (typeof saveMaestroCodigoLS === "function" && !saveMaestroCodigoLS._ghWrapped) {
      const o = saveMaestroCodigoLS;
      saveMaestroCodigoLS = function() { const r = o.apply(this, arguments); ghMarkDirty("codigo"); return r; };
      saveMaestroCodigoLS._ghWrapped = true;
    }
  } catch (e) {}
  try {
    if (typeof saveUsers === "function" && !saveUsers._ghWrapped) {
      const o = saveUsers;
      saveUsers = function() { const r = o.apply(this, arguments); ghMarkDirty("usuarios"); return r; };
      saveUsers._ghWrapped = true;
    }
  } catch (e) {}
}

let _ghAutoTimer = null;
function ghStartAutoSync(on) {
  if (_ghAutoTimer) { clearInterval(_ghAutoTimer); _ghAutoTimer = null; }
  try { localStorage.setItem("rutalog_gh_auto", on ? "1" : "0"); } catch (e) {}
  if (typeof ghStartPullLoop === "function") ghStartPullLoop(!!on);
  if (!on) return;
  // Primera pasada a los ~8 s
  setTimeout(function() {
    if (document.hidden) return;
    if (!ghGetToken()) return;
    ghActualizar({ silent: true });
  }, 8 * 1000);
  // Respaldo cada 2 min (además del pull cada 60 s y el push a 1.5 s tras editar)
  _ghAutoTimer = setInterval(function() {
    if (document.hidden) return;
    if (!ghGetToken()) return;
    ghActualizar({ silent: true });
  }, 2 * 60 * 1000);
}


// ===== Toque: respuesta inmediata en móvil/tablet (sin esperar solo al click) =====
(function enhanceTouch() {
  function isCoarse() {
    try {
      return window.matchMedia && window.matchMedia("(hover: none) and (pointer: coarse)").matches;
    } catch (e) { return "ontouchstart" in window; }
  }
  // Activar :active en iOS
  document.addEventListener("touchstart", function() {}, { passive: true });

  // Drop zones: abrir file picker también con touch
  document.querySelectorAll(".drop").forEach(function(z) {
    z.addEventListener("touchend", function(e) {
      // dejar que click nativo funcione; solo evitar scroll accidental largo
      if (e.cancelable && e.changedTouches && e.changedTouches.length === 1) {
        // no preventDefault para no romper el onclick
      }
    }, { passive: true });
  });

  // Checkboxes de auditoría / chips: área de toque más grande vía label ya cubierto
  // Leaflet: invalidar tamaño al abrir drawer o rotar (ya hay resize)
  if (isCoarse()) {
    document.documentElement.classList.add("touch-ui");
  }
})();

(function initGitHubSync() {
  const tok = document.getElementById("syncToken");
  if (tok) tok.value = ghGetToken();
  const btnToggleToken = document.getElementById("btnToggleToken");
  if (btnToggleToken && tok) {
    btnToggleToken.onclick = function () {
      try {
        const users = (typeof loadUsers === "function" ? loadUsers() : []).filter(function (x) { return x.activo !== false; });
        const u = typeof usuarioActual === "function" ? usuarioActual() : null;
        const canSee = !users.length || (u && u.rol === "admin");
        if (!canSee) {
          if (typeof toast === "function") toast("Solo un administrador puede ver el token");
          return;
        }
        if (tok.type === "password") {
          tok.type = "text";
          btnToggleToken.textContent = "Ocultar";
        } else {
          tok.type = "password";
          btnToggleToken.textContent = "Ver";
        }
      } catch (e) {
        console.warn(e);
      }
    };
  }
  ghUpdateSyncBadge();
  ghSetMeta(ghGetMeta());
  ghInstallDirtyHooks();

  const btnSave = document.getElementById("btnSaveToken");
  if (btnSave) btnSave.onclick = async () => {
    const v = (document.getElementById("syncToken") || {}).value || "";
    ghSetToken(v.trim());
    if (!v.trim()) {
      toast("Token vacío");
      return;
    }
    toast("Token guardado · sincronizando usuarios…");
    try {
      const autoEl = document.getElementById("syncAuto");
      if (autoEl && autoEl.checked) ghStartAutoSync(true);
      await ghActualizar({ silent: false });
      if (typeof aplicarGateLoginDesdeSync === "function") aplicarGateLoginDesdeSync();
    } catch (e) {
      console.warn(e);
    }
  };
  const btnClear = document.getElementById("btnClearToken");
  if (btnClear) btnClear.onclick = () => {
    ghSetToken("");
    if (tok) tok.value = "";
    toast("Token eliminado");
  };
  const btnAct = document.getElementById("btnSyncActualizar");
  if (btnAct) btnAct.onclick = async () => {
    await ghActualizar({ silent: false });
    if (typeof aplicarGateLoginDesdeSync === "function") aplicarGateLoginDesdeSync();
  };

  const auto = document.getElementById("syncAuto");
  // Por defecto ON: usuarios (operadores/admin) y datos se guardan en GitHub automática tras editar y cada minuto
  let autoOn = true;
  try {
    const stored = localStorage.getItem("rutalog_gh_auto");
    if (stored === "0") autoOn = false;
    else if (stored === "1") autoOn = true;
    else autoOn = true; // nunca configurado → activar
  } catch (e) { autoOn = true; }
  if (auto) {
    auto.checked = autoOn;
    auto.onchange = () => ghStartAutoSync(!!auto.checked);
  }
  if (autoOn && ghGetToken()) ghStartAutoSync(true);
  else if (autoOn) {
    // Token aún no: dejar preferencia ON; al guardar token se arranca
    try { localStorage.setItem("rutalog_gh_auto", "1"); } catch (e) {}
  }

  // Primera sincronización al abrir (si hay token)
  setTimeout(function() {
    if (ghGetToken()) ghActualizar({ silent: true });
  }, 2000);

  // Al volver a la pestaña / ventana: bajar cambios de otras PCs
  document.addEventListener("visibilitychange", function() {
    if (typeof ghOnVisibilitySync === "function") ghOnVisibilitySync();
  });
  window.addEventListener("focus", function() {
    if (typeof ghOnVisibilitySync === "function") ghOnVisibilitySync();
  });
})();


// ============ MEJORA-6: Optimizar orden de paradas (vecino más cercano) ============
function distKm(a, b) {
  if (!a || !b || a.lat == null || b.lat == null) return 1e9;
  const R = 6371;
  const toR = Math.PI / 180;
  const dLat = (b.lat - a.lat) * toR;
  const dLon = (b.lon - a.lon) * toR;
  const la1 = a.lat * toR, la2 = b.lat * toR;
  const h = Math.sin(dLat/2)**2 + Math.cos(la1)*Math.cos(la2)*Math.sin(dLon/2)**2;
  return 2 * R * Math.asin(Math.min(1, Math.sqrt(h)));
}

function optimizarOrdenParadas() {
  const paradas = estado.viajeActual;
  if (!paradas || paradas.length < 2) {
    toast("Se necesitan al menos 2 paradas");
    return;
  }
  const origen = estado.origenActual || { lat: paradas[0].lat, lon: paradas[0].lon };
  const pending = [...paradas];
  const ordered = [];
  let cur = origen;
  while (pending.length) {
    let bestI = 0, bestD = 1e18;
    for (let i = 0; i < pending.length; i++) {
      const d = distKm(cur, pending[i]);
      if (d < bestD) { bestD = d; bestI = i; }
    }
    const next = pending.splice(bestI, 1)[0];
    ordered.push(next);
    cur = next;
  }
  estado.viajeActual = ordered;
  if (typeof refrescarRutaUI === "function") refrescarRutaUI();
  if (typeof renderMapas === "function") renderMapas();
  toast("Orden optimizado · " + ordered.length + " paradas");
}

function initOptimizarRutaButton() {
  const btn = document.getElementById("btnOptimizarRuta");
  if (!btn) return;
  btn.onclick = optimizarOrdenParadas;
  // Habilitar cuando haya paradas: hook into refrescarRutaUI if possible
  const prev = window.refrescarRutaUI;
  // lightweight: poll via Mutation or patch after refrescar
  const sync = () => {
    const n = (estado.viajeActual && estado.viajeActual.length) || 0;
    btn.disabled = n < 2;
  };
  if (typeof refrescarRutaUI === "function") {
    const orig = refrescarRutaUI;
    window.refrescarRutaUI = function () {
      const r = orig.apply(this, arguments);
      try { sync(); } catch (e) {}
      return r;
    };
  }
  sync();
}


